        return final_res

    def modulo(self, a: float, b: float) -> float:
        """Calculates the remainder of a divided by b."""
        if b == 0:
            raise ValueError("Modulo by zero")
        res = float(a % b)
        self._record("modulo", a, b, res)
        return res

    def get_history(self) -> list[tuple[str, float, float, float]]:
        """Returns a copy of the operation history."""
        return list(self._history)

    def clear_history(self) -> None:
        """Clears all stored operation history."""
        self._history = []

    def evaluate(self, expression: str) -> float:
        """Parses and evaluates a string expression with basic arithmetic."""
        def _eval(node: Any) -> float:
            if isinstance(node, ast.Constant):
                if not isinstance(node.value, (int, float)):
                    raise ValueError(f"Unsupported constant type: {type(node.value)}")
                return float(node.value)

            if isinstance(node, ast.BinOp):
                left = _eval(node.left)
                right = _eval(node.right)

                if isinstance(node.op, ast.Add): return left + right
                if isinstance(node.op, ast.Sub): return left - right
                if isinstance(node.op, ast.Mult): return left * right
                if isinstance(node.op, ast.Div):
                    if right == 0: raise ValueError("Division by zero")
                    return left / right
                if isinstance(node.op, ast.Pow):
                    res = pow(left, right)
                    if isinstance(res, complex): raise ValueError("Result is imaginary")
                    return float(res)
                if isinstance(node.op, ast.Mod):
                    if right == 0: raise ValueError("Modulo by zero")
                    return left % right
                raise ValueError(f"Unsupported operator: {type(node.op).__name__}")

            if isinstance(node, ast.UnaryOp):
                operand = _eval(node.operand)
                if isinstance(node.op, ast.USub): return -operand
                if isinstance(node.op, ast.UAdd): return operand
                raise ValueError(f"Unsupported unary operator: {type(node.op).__name__}")

            raise ValueError(f"Unsupported syntax: {type(node).__name__}")

        try:
            tree = ast.parse(expression, mode='eval')
            result = float(_eval(tree.body))
            self._record("evaluate", 0.0, 0.0, result)
            return result
        except (SyntaxError, TypeError, ZeroDivisionError, ValueError) as e:
            raise ValueError(f"Evaluation error: {e}")

    def memory_store(self, value: float) -> None:
        """Stores a value in memory."""
        self._memory = float(value)
        self._record("memory_store", value, 0.0, float(value))

    def memory_recall(self) -> float:
        """Returns the currently stored value."""
        if self._memory is None:
            raise ValueError("Memory is empty")
        return self._memory

    def memory_clear(self) -> None:
        """Resets memory to None."""
        self._memory = None
        self._record("memory_clear", 0.0, 0.0, 0.0)
